require __DIR__.'/common.php';method('POST');$u=uid();$b=json_decode(file_get_contents('php://input'),true)?:[];$id=$b['order_id']??'';if(!preg_match('/^ix_[a-f0-9]{24}$/',$id) out(400,['error'=>'invalid_order']);$pdo=db();$q=$pdo->prepare('SELECT * FROM orders WHERE order_id=? AND user_id=?');$q->execute([$id,$u]);$o=$q->fetch(PDO::FETCH_ASSOC);if(!$o)out(404,['error'=>'order_not_found']);$cfOrder=cf('GET','/orders/'.$id);if(($cfOrder['order_status']??'')!=='PAID')out(200,['status'=>$cfOrder['order_status']??'UNKNOWN','premium_unlocked'=>false]);$payments=cf('GET','/orders/'.$id.'/payments');$ok=false;$pid=null;foreach($payments as $payment){if(($payment['payment_status']??'')==='SUCCESS'&&(float)($payment['payment_amount']??0)===(float)$o['amount']){$ok=true;$pid=(string)($payment['cf_payment_id']??'');break;}}if(!$ok)out(200,['status'=>'not_verified','premium_unlocked'=>false]);$p=$config['plans'][$o['plan']];$expiry=$p['days']===null?null:gmdate('c',time()+$p['days']*86400);$pdo->prepare('UPDATE orders SET status="PAID",payment_id=?,expires_at=? WHERE order_id=?')->execute([$pid,$expiry,$id]);$pdo->prepare('INSERT INTO entitlements(user_id,plan,expires_at,updated_at) VALUES(?,?,?,?) ON CONFLICT(user_id) DO UPDATE SET plan=excluded.plan,expires_at=excluded.expires_at,updated_at=excluded.updated_at')->execute([$u,$o['plan'],$expiry,gmdate('c')]);out(200,['status'=>'PAID','premium_unlocked'=>true,'plan'=>$o['plan'],'expires_at'=>$expiry]);
